def select_next_node(graph, unvisited_nodes):
    import math

    unvisited_set = set(unvisited_nodes)

    active_deg_map = {}
    for node in unvisited_set:
        active_deg_map[node] = sum(1 for nb in graph.neighbors(node) if nb in unvisited_set)

    max_active_deg = max(active_deg_map.values(), default=1) or 1
    max_core_val = max((graph.nodes[n]['core_number'] for n in unvisited_nodes), default=1) or 1

    # Approximate dominant eigenvector entry via local power iteration:
    # x_v ≈ (1/d_v) * sum_{u in N(v)} (1/d_u) * sum_{w in N(u)} (1/d_w)
    # This is a 2-hop normalized adjacency walk (power iteration approximation)

    # Step 1: compute 1-hop smoothed value for each node
    # h1[v] = sum_{u in N(v)} 1/sqrt(d_u + 1)
    h1 = {}
    for node in unvisited_set:
        val = 0.0
        for nb in graph.neighbors(node):
            if nb in unvisited_set:
                val += 1.0 / math.sqrt(active_deg_map[nb] + 1)
        h1[node] = val

    # Step 2: compute 2-hop smoothed value
    # h2[v] = sum_{u in N(v)} h1[u] / sqrt(d_u + 1)
    h2 = {}
    for node in unvisited_set:
        val = 0.0
        for nb in graph.neighbors(node):
            if nb in unvisited_set:
                val += h1[nb] / math.sqrt(active_deg_map[nb] + 1)
        h2[node] = val

    max_h2 = max(h2.values(), default=1e-9) or 1e-9

    # Step 3: Neighborhood conductance disruption
    # For each node v, estimate the "cut" created by removing v:
    # conductance_cut[v] = edges from N(v) to outside N(v) union {v} / total edges of N(v)
    # This captures how much v bridges different parts of the graph

    best_node = None
    best_score = -1e18

    for node in unvisited_nodes:
        d_v = active_deg_map[node]
        neighbors_1 = [nb for nb in graph.neighbors(node) if nb in unvisited_set]
        nb_set = set(neighbors_1)

        # Spectral contribution: normalized 2-hop walk score
        spectral_score = h2[node] / (max_h2 + 1e-9)

        # Degree-weighted spectral impact:
        # How much does removing v reduce the total quadratic form x^T A x?
        # Approximated as: sum_{u in N(v)} h2[u] * (1/sqrt(d_v+1)) / sqrt(d_u+1)
        quadratic_impact = 0.0
        for nb in neighbors_1:
            quadratic_impact += h2[nb] / (math.sqrt(d_v + 1) * math.sqrt(active_deg_map[nb] + 1))
        max_possible_qi = max_h2 * d_v / (1 + 1e-9)
        norm_qi = quadratic_impact / (max_possible_qi + 1e-9)

        # Neighborhood conductance cut:
        # Count edges within N(v) vs edges from N(v) to outside
        internal_edges = 0
        external_edges = 0
        for nb1 in neighbors_1:
            for nb2 in graph.neighbors(nb1):
                if nb2 in unvisited_set and nb2 != node:
                    if nb2 in nb_set:
                        internal_edges += 1
                    else:
                        external_edges += 1

        internal_edges //= 2  # each counted twice
        total_nb_edges = internal_edges + external_edges
        if total_nb_edges > 0:
            conductance_cut = external_edges / (total_nb_edges + 1e-9)
        else:
            conductance_cut = 0.0

        # Volume ratio: how much of the graph's edge weight flows through v
        vol_v = d_v / (max_active_deg + 1e-9)

        # Fragmentation potential via neighbor component entropy
        frag_score = 0.0
        if len(neighbors_1) >= 2:
            parent = {n: n for n in neighbors_1}
            sz = {n: 1 for n in neighbors_1}

            def find(x):
                while parent[x] != x:
                    parent[x] = parent[parent[x]]
                    x = parent[x]
                return x

            def union(a, b):
                ra, rb = find(a), find(b)
                if ra != rb:
                    if sz[ra] < sz[rb]:
                        ra, rb = rb, ra
                    parent[rb] = ra
                    sz[ra] += sz[rb]

            for nb1 in neighbors_1:
                for nb2 in graph.neighbors(nb1):
                    if nb2 in nb_set and nb2 != nb1:
                        union(nb1, nb2)

            comp_sizes = {}
            for nb1 in neighbors_1:
                r = find(nb1)
                comp_sizes[r] = comp_sizes.get(r, 0) + 1

            n_comps = len(comp_sizes)
            if n_comps > 1:
                total = len(neighbors_1)
                # Gini-like dispersion: maximize when components are equal size
                entropy = 0.0
                for sz_val in comp_sizes.values():
                    p = sz_val / total
                    entropy -= p * math.log(p + 1e-9)
                max_entropy = math.log(n_comps + 1e-9)
                frag_score = (entropy / (max_entropy + 1e-9)) * math.log1p(n_comps)

        # Composite spectral-conductance score
        # Fundamentally: spectral disruption * conductance_cut amplified by fragmentation
        score = (
            0.35 * spectral_score +
            0.25 * norm_qi +
            0.20 * conductance_cut * (1.0 + vol_v) +
            0.20 * frag_score
        )

        if score > best_score:
            best_score = score
            best_node = node

    return best_node
